ALTER TABLE subcontract_boq_items ADD COLUMN pricing_type VARCHAR(20) NOT NULL DEFAULT 'quantity' AFTER description, ADD COLUMN lump_sum_amount DECIMAL(18,2) NULL AFTER unit_rate, DROP COLUMN line_total, ADD COLUMN line_total DECIMAL(18,2) GENERATED ALWAYS AS (CASE WHEN pricing_type='lump_sum' THEN lump_sum_amount ELSE ROUND(quantity*unit_rate,2) END) STORED, ADD CONSTRAINT chk_subcontract_boq_item_pricing_type CHECK(pricing_type IN('quantity','lump_sum')), ADD CONSTRAINT chk_subcontract_boq_item_lump_sum CHECK((pricing_type='quantity' AND lump_sum_amount IS NULL) OR (pricing_type='lump_sum' AND lump_sum_amount IS NOT NULL AND lump_sum_amount>=0));
